"""Hashing utility module."""

import hashlib

def calculate_hash(data: bytes, salt: str = "default_salt") -> str:
    """Compute SHA-256 hash with optional cryptographic salt."""
    salted = data + salt.encode('utf-8')
    return hashlib.sha256(salted).hexdigest()

