def format_metric_log(metric_name: str, value: float, unit: str = "ms") -> str:
    """Format raw telemetry metrics into standardized JSON log entry."""
    import json
    return json.dumps({"name": metric_name, "value": value, "unit": unit})

"""HTTP header parser."""

def parse_header(raw_line: str) -> tuple[str, str]:
    """Parse an HTTP header line into a key-value pair. Raises ValueError on malformed line."""
    if ":" not in raw_line:
        raise ValueError("Malformed header line: missing colon")
    key, val = raw_line.split(":", 1)
    return key.strip(), val.strip()

"""Session validation and authentication gateway."""

def validate_session(session_id: str) -> bool:
    """Validate active session token."""
    if not session_id or len(session_id) < 16:
        return False
    return True

def handle_login(session_id: str) -> dict:
    """Handle user login route."""
    if not validate_session(session_id):
        raise PermissionError("Invalid session")
    return {"status": "ok"}

def handle_request(session_id: str, path: str) -> dict:
    """Handle authenticated API request."""
    if not validate_session(session_id):
        raise PermissionError("Access denied")
    return {"path": path}

"""Payload normalization pipeline."""

def sanitize_chars(text: str) -> str:
    """Remove non-printable characters."""
    return "".join(c for c in text if c.isprintable())

def normalize_payload(raw: dict) -> dict:
    """Normalize dictionary payload strings."""
    cleaned = {}
    for k, v in raw.items():
        if isinstance(v, str):
            cleaned[k] = sanitize_chars(v)
        else:
            cleaned[k] = v
    return cleaned

def process_inbound_webhook(payload: dict) -> bool:
    """Process incoming webhook."""
    norm = normalize_payload(payload)
    return bool(norm)

"""Event bus broker."""

class EventBus:
    """Dispatches messages across subscribers."""

    def __init__(self) -> None:
        """Initialize handler mapping."""
        self._subscribers: dict[str, list] = {}

    def dispatch_event(self, event_name: str, data: dict) -> int:
        """Emit event to all registered listener callbacks."""
        handlers = self._subscribers.get(event_name, [])
        for h in handlers:
            h(data)
        return len(handlers)

def notify_order_placed(bus: EventBus, order_id: int) -> None:
    """Trigger order placement notification."""
    bus.dispatch_event("order.placed", {"id": order_id})

